private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            {
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "1")
                {
                    e.Cancel = true;
                }
            }
}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            xrLabel21.Text = String.Format("{0:#,#.00}", totaliArketuar - totaliPaguar + gjendjamepare);    
}

private void xrLabel15_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("NRLLOGARI") != null)
                totaliArketuar = Convert.ToDouble(xrLabel15.Summary.GetResult());
}

private void xrLabel16_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("NRLLOGARI") != null)
                totaliPaguar = Convert.ToDouble(xrLabel16.Summary.GetResult());
}

private void xrTableCell40_AfterPrint(object sender, System.EventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
            {
                gjendjamepare = Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString());
            }
            progresivi = gjendjamepare;
}

private void xrTableCell40_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
                if (Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()) >=0)
                    xrTableCell40.Text = String.Format("{0:#,#.00}",  Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()));
                else
                    xrTableCell40.Text = String.Format("{0:#,#.00}", 0);
}

private void xrLabel11_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            xrLabel11.Text = String.Format("{0:#,#.00}", progresivi);
}

private void xrLabel9_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
        if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")
                    progresivi = progresivi + Convert.ToDouble(GetCurrentColumnValue("VLERA"));
}

private void xrLabel10_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
        if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "pagese")
                    progresivi = progresivi - Convert.ToDouble(GetCurrentColumnValue("VLERA"));
}

private void xrTableCell4_AfterPrint(object sender, System.EventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
            {
                gjendjamepare = Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString());
            }
            progresivi = gjendjamepare;
}

private void xrTableCell4_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
                if (Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()) <= 0)
                    xrTableCell4.Text = String.Format("{0:#,#.00}", -Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()));
                else
                    xrTableCell4.Text = String.Format("{0:#,#.00}", 0);
}

private void xrTableCell36_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
System.Resources.ResourceManager rm = new System.Resources.ResourceManager("Resources.Strings",
                       System.Reflection.Assembly.Load("App_GlobalResources")); 
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

            if (Convert.ToBoolean(GetCurrentColumnValue("LLOJARKABANKA")))
            {
                xrTableCell36.Text = rm.GetString("labelRaportKomision", parametraRaporti.Ci) + ":"; 
            }
            else
            {
                xrTableCell36.Text = "";
            }
}

private void xrTableCell32_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
