 string scopeID = parametraRaporti.ScopeID;

 if (GetCurrentColumnValue("IDDOKUMENTI") != null)
            {
                       xrLabel1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('ShtoVeprimBanka.aspx?scopeID="+scopeID+"&newScopeId=True&lloji=" + GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() + "&id=" + GetCurrentColumnValue("IDDOKUMENTI").ToString() + "&numer=" + GetCurrentColumnValue("NRDOKUMENTI").ToString() + "&shtim_modifikim=modifikim')";
